import{_ as a,C as i,o as n,c as d,j as t,a as s,E as r,ao as h}from"./chunks/framework.DOMnz-Zz.js";const f=JSON.parse('{"title":"Modes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/modes.md","filePath":"guide/modes.md","lastUpdated":null}'),l={name:"guide/modes.md"};function c(p,e,u,g,y,m){const o=i("DemoLoop");return n(),d("div",null,[e[0]||(e[0]=t("h1",{id:"Modes",tabindex:"-1"},[s("Modes "),t("a",{class:"header-anchor",href:"#Modes","aria-label":'Permalink to "Modes {#Modes}"'},"​")],-1)),e[1]||(e[1]=t("p",null,[s("A "),t("strong",null,"mode"),s(" is a switchable root for the navigation tree. Every mode has the same shape — a parent → current → children hierarchy shown as a collapsible outline — and a hotkey swaps which tree fills it. "),t("strong",null,"Cursor position is preserved per mode"),s(" across switches, so jumping from Files to Modules and back lands you exactly where you left each one.")],-1)),r(o,{name:"modules",caption:"Modules mode: the cursor moves through a module's definitions, with docstring and source in the preview."}),e[2]||(e[2]=h('<p>The four navigation modes are native Rust views in the frontend: Files, Modules, Sessions and Hosts. Files, Sessions and Hosts are built in Rust; the Modules tree comes from the Julia kernel. The former <code>Mode</code> extension type has been removed from core. <a href="https://github.com/kalidke/ship-of-tools/blob/main/docs/history/adr/0051-mods.md#the-mod" target="_blank" rel="noreferrer">ADR 0051</a> specifies future view extensions as <code>Mod</code> subtypes with <code>tree_children</code> and the three-argument <code>preview</code>, shown in a generic Mods navigation mode. The mod system is planned for a 0.7.Z after the 0.7.0 tag and is not built. The planned Agents and Outputs views become mods under that decision. See <a href="./../extend/abi">The Dispatch ABI</a> for the current extension surface.</p><h2 id="The-same-shape-everywhere" tabindex="-1">The same shape everywhere <a class="header-anchor" href="#The-same-shape-everywhere" aria-label="Permalink to &quot;The same shape everywhere {#The-same-shape-everywhere}&quot;">​</a></h2><p>The window&#39;s navigation pane is a single collapsible tree: a parent context, the current level, and its children, shown through nesting. What changes between modes is <em>what</em> the tree enumerates and what the preview pane shows for the cursored node.</p><h2 id="The-nav-modes-bound-today" tabindex="-1">The nav modes bound today <a class="header-anchor" href="#The-nav-modes-bound-today" aria-label="Permalink to &quot;The nav modes bound today {#The-nav-modes-bound-today}&quot;">​</a></h2><p>The frontend binds four navigation modes. Each is a single-character chord that is active <strong>only in navigation focus</strong> — in the pty panes, the editor, or a prompt, those characters stay literal text.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Mode</th><th style="text-align:right;">What it roots the tree at</th></tr></thead><tbody><tr><td style="text-align:right;"><code>f</code></td><td style="text-align:right;">Files</td><td style="text-align:right;">the project filesystem</td></tr><tr><td style="text-align:right;"><code>m</code></td><td style="text-align:right;">Modules</td><td style="text-align:right;">modules and their definitions (types, functions, macros and submodules), read-only, from <code>JuliaSyntax.jl</code></td></tr><tr><td style="text-align:right;"><code>s</code></td><td style="text-align:right;">Sessions</td><td style="text-align:right;">workspaces — the projects this backend is hosting</td></tr><tr><td style="text-align:right;"><code>h</code></td><td style="text-align:right;">Hosts</td><td style="text-align:right;">the remote hosts you can target</td></tr></tbody></table><p>Files and Modules navigate the project. Sessions and Hosts navigate the deployment surface: which project and which machine.</p><h3 id="Sessions-mode-s" tabindex="-1">Sessions mode (<code>s</code>) <a class="header-anchor" href="#Sessions-mode-s" aria-label="Permalink to &quot;Sessions mode (`s`) {#Sessions-mode-s}&quot;">​</a></h3><p>Sessions mode lists the workspaces the backend knows about and lets you commit a new one. The session picker uses three chords on the cursored directory:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Chord</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Enter</code></td><td style="text-align:right;">Create a workspace with a Claude Code agent.</td></tr><tr><td style="text-align:right;"><code>Ctrl+Enter</code></td><td style="text-align:right;">Create a workspace with a Codex agent.</td></tr><tr><td style="text-align:right;"><code>Shift+Enter</code></td><td style="text-align:right;">Create a workspace with a plain shell and no agent.</td></tr></tbody></table><p>One backend daemon hosts one Julia kernel per workspace, routed by <code>workspace_id</code>, so switching workspaces is fast and does not tear down the kernel — switching is &quot;like tmux windows in the same session.&quot; You can also cycle the active workspace directly with <code>Shift+ArrowRight</code> / <code>Shift+ArrowLeft</code>.</p><h4 id="Accounts" tabindex="-1">Accounts <a class="header-anchor" href="#Accounts" aria-label="Permalink to &quot;Accounts {#Accounts}&quot;">​</a></h4><p>A session normally runs under the agent&#39;s default login. To spend a <em>different</em> subscription — a team account, say, kept separate from your personal one — add an account outside Ship of Tools first:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude-auth/team</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/.claude-auth/team</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> claude</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># then, inside that claude session: /login</span></span></code></pre></div><p>Once that subdirectory exists it appears as a choice in the session picker (<code>Tab</code> cycles it) — Ship of Tools discovers accounts, it never declares or creates them, and it never stores a credential of any kind. A subdirectory you haven&#39;t logged into yet still shows up and is still selectable — the row&#39;s own pane runs the login on its first start. Sessions running under a non-default account show a short <code>· &lt;name&gt;</code> suffix in the Sessions list so you can tell at a glance which subscription each one spends.</p><p>An account folder holds only its own login and Claude&#39;s own per-account runtime state (sessions, caches, and the like). Everything else — <code>CLAUDE.md</code>, <code>settings.json</code> (hooks, permissions, model, status line), <code>agents</code>, <code>commands</code>, <code>skills</code>, <code>plugins</code>, <code>output-styles</code>, per-project memory (<code>projects</code>), and prompt history (<code>history.jsonl</code>) — is <strong>shared with the default folder</strong>: on the first session in a new account, the daemon links each of those entries in from <code>~/.claude</code>, so the account starts with the same instructions, hooks, and history as the default login. An entry already present in the account folder — created by you, or from an earlier session — is kept as is and overrides the shared one; to use the shared one instead, remove the account&#39;s own copy. The Ship of Tools skills and work-state hooks are not in any of these folders: a session Ship of Tools starts carries them itself (the skills from <code>~/.sot-comm/claude-layer</code>, the hooks in its own launch settings), whichever account it runs as. The two mail hooks are the exception: every install and update merges them into an account&#39;s own <code>settings.json</code>. User-scope MCP servers live with the per-account state, so add them separately for each account you want to use them from.</p><p>On Windows, a symlink needs Developer Mode or the symlink privilege, and a standard desktop user has neither. Where the daemon cannot make a symlink, it shares each folder through a <strong>junction</strong>, which needs no privilege, and checks that it can read through it; if it cannot, it removes the junction and the session does not start, naming the reason. <code>CLAUDE.md</code>, <code>settings.json</code> and <code>history.jsonl</code> become <strong>copies</strong>, made once at the account&#39;s first session and its own after: later changes to the default&#39;s file do not reach the account, and the account&#39;s do not reach the default (a file the default lacks is not created). Two limits follow. A junction made by a non-administrator cannot be crossed by a process that enforces redirection trust, such as an ssh session on a host that sets it for <code>sshd.exe</code> or a process a system service starts; the desktop does not enforce it. And a junction works on a local NTFS or ReFS volume only. To share the three files by symlink instead, an administrator turns on Developer Mode (Settings, System, For developers; a standard user cannot), and then, with no session running in that account and after saving anything you want from its copies:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$acct </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\.claude-auth\\team&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;CLAUDE.md&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;settings.json&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;history.jsonl&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Remove-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LiteralPath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$acct</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ErrorAction SilentlyContinue }</span></span></code></pre></div><p>The next session in that account links each file the default folder has. The folders keep the junctions already made, with the same redirection-trust limit. Without an administrator, the copies stay the account&#39;s own.</p><p>An account name is lowercase letters, digits, <code>-</code>, and <code>_</code> only, and must start with a letter or digit — <code>team</code>, <code>team-2</code>, and <code>a_b</code> all work, <code>Team</code> and <code>../etc</code> do not.</p><p>Claude only, this release — Codex accounts are deferred, so a codex row always runs the default login.</p><h3 id="hosts-mode" tabindex="-1">Hosts mode (<code>h</code>) <a class="header-anchor" href="#hosts-mode" aria-label="Permalink to &quot;Hosts mode (`h`) {#hosts-mode}&quot;">​</a></h3><p>Hosts mode lists every daemon host the frontend is connected to. The frontend dials every daemon host declared in <code>hosts.toml</code> at once, so each row shows whether that host is connected or unreachable, or, when its daemon answered and refused this window, why (<code>daemon out of date</code> for a daemon still running an older version than the window speaks), tagged <code>[current]</code> for the host you are working on and <code>[default]</code> for the first connection. <code>Enter</code> on a host moves the Sessions view to that host&#39;s group; there is nothing to relaunch.</p><p>The launcher&#39;s primary host is the hub unless <code>SOT_HOST_NAME</code> (or <code>SOT_HOST</code>) names another.</p><h2 id="Switching,-focus,-and-layout-keys" tabindex="-1">Switching, focus, and layout keys <a class="header-anchor" href="#Switching,-focus,-and-layout-keys" aria-label="Permalink to &quot;Switching, focus, and layout keys {#Switching,-focus,-and-layout-keys}&quot;">​</a></h2><p>Mode switches share the keymap with pane focus and layout. The relevant chords:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Chord</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>f</code> / <code>m</code> / <code>s</code> / <code>h</code></td><td style="text-align:right;">switch nav mode (nav focus only)</td></tr><tr><td style="text-align:right;"><code>Shift+ArrowLeft</code> / <code>Shift+ArrowRight</code></td><td style="text-align:right;">cycle the active workspace</td></tr><tr><td style="text-align:right;"><code>Ctrl+ArrowLeft/Right/Up/Down</code></td><td style="text-align:right;">move pane focus (4-way, spatial)</td></tr><tr><td style="text-align:right;"><code>Alt+=</code></td><td style="text-align:right;">maximize the focused pane; <code>Escape</code> restores</td></tr><tr><td style="text-align:right;"><code>Ctrl+j</code> / <code>Ctrl+t</code> / <code>Ctrl+m</code></td><td style="text-align:right;">toggle the REPL / Terminal / Monitor drawers</td></tr><tr><td style="text-align:right;"><code>Ctrl+?</code></td><td style="text-align:right;">show pane actions briefly; press again for the Help drawer</td></tr><tr><td style="text-align:right;"><code>F1</code></td><td style="text-align:right;">open or close the Help drawer</td></tr></tbody></table><p>Because the mode keys are plain single characters, they are deliberately scoped to navigation focus — the keymap matches them only when a nav pane is focused, so typing <code>f</code> into the REPL or the editor inserts an <code>f</code>. The authoritative chord list lives in <a href="./../ref/keybindings">Keybindings</a>.</p>',28))])}const w=a(l,[["render",c]]);export{f as __pageData,w as default};
